// pyfloat.mjs
// Emulation of CPython's float() string parsing and repr() formatting,
// which the original script relies on implicitly (argparse type=float and
// moneyed's Decimal(str(amount)) conversion).

const PY_WS = ' \t\n\r\v\f';

function stripPyWhitespace(s) {
  let start = 0;
  let end = s.length;
  while (start < end && PY_WS.includes(s[start])) start++;
  while (end > start && PY_WS.includes(s[end - 1])) end--;
  return s.slice(start, end);
}

// Python numeric grammar: digitpart = digit (["_"] digit)*
const DIGIT_PART = '\\d(?:_?\\d)*';
const FLOAT_RE = new RegExp(
  '^[+-]?(?:' +
    DIGIT_PART + '\\.?(?:' + DIGIT_PART + ')?' + // "1", "1.", "1.5"
    '|\\.' + DIGIT_PART + // ".5"
  ')(?:[eE][+-]?' + DIGIT_PART + ')?$'
);
const INF_NAN_RE = /^[+-]?(?:inf(?:inity)?|nan)$/i;

export class PyFloatError extends Error {}

// Parse a string exactly like CPython's float(). Throws PyFloatError on
// invalid input. Returns a JS number.
export function pyFloat(s) {
  const t = stripPyWhitespace(s);
  if (INF_NAN_RE.test(t)) {
    const negative = t[0] === '-';
    const body = t.replace(/^[+-]/, '').toLowerCase();
    if (body.startsWith('inf')) return negative ? -Infinity : Infinity;
    return NaN;
  }
  if (!FLOAT_RE.test(t)) throw new PyFloatError(`could not convert string to float: ${s}`);
  return Number(t.replace(/_/g, ''));
}

// Format a JS number exactly like CPython's repr(float).
// Python uses the shortest round-trip digits (same as JS Number#toExponential
// without arguments) and then formats fixed for -4 < decpt <= 16, else
// exponential with a signed, at-least-two-digit exponent.
export function pyFloatRepr(x) {
  if (Number.isNaN(x)) return 'nan';
  if (x === Infinity) return 'inf';
  if (x === -Infinity) return '-inf';

  const negative = x < 0 || Object.is(x, -0);
  const sign = negative ? '-' : '';
  const a = negative ? -x : x;

  let digits;
  let decpt;
  if (a === 0) {
    digits = '0';
    decpt = 0;
  } else {
    const [mantissa, expStr] = a.toExponential().split('e');
    digits = mantissa.replace('.', '');
    decpt = Number(expStr) + 1; // value = 0.digits * 10^decpt
  }

  if (decpt > 16 || decpt < -3) {
    const mant = digits.length > 1 ? digits[0] + '.' + digits.slice(1) : digits;
    const e = decpt - 1;
    const expText = (e < 0 ? '-' : '+') + String(Math.abs(e)).padStart(2, '0');
    return sign + mant + 'e' + expText;
  }

  if (decpt <= 0) return sign + '0.' + '0'.repeat(-decpt) + digits;
  if (decpt >= digits.length) {
    return sign + digits + '0'.repeat(decpt - digits.length) + '.0';
  }
  return sign + digits.slice(0, decpt) + '.' + digits.slice(decpt);
}

