// pydecimal.mjs
// Minimal re-implementation of Python's decimal.Decimal covering exactly what
// the original script exercises: construction from a string (as produced by
// Python's float repr), exact division by 2 under the default context
// (28 significant digits — any halved float-repr fits, so results are always
// exact), and str().

export class PyDecimal {
  // sign: '' | '-'; digits: coefficient without leading zeros ('0' for zero);
  // exp: base-10 exponent; special: null | 'Infinity' | 'NaN'
  constructor(sign, digits, exp, special = null) {
    this.sign = sign;
    this.digits = digits;
    this.exp = exp;
    this.special = special;
  }
}

// Parse a string the way Decimal(str) does for the outputs of Python's float
// repr: optional sign, "inf"/"nan", digits with optional fraction and/or
// exponent part. Trailing zeros of the coefficient are preserved, matching
// Decimal (Decimal('100.0') keeps exponent -1).
export function decimalFromString(s) {
  let sign = '';
  let body = s;
  if (body[0] === '-' || body[0] === '+') {
    if (body[0] === '-') sign = '-';
    body = body.slice(1);
  }
  const lower = body.toLowerCase();
  if (lower === 'inf' || lower === 'infinity') return new PyDecimal(sign, '0', 0, 'Infinity');
  if (lower === 'nan') return new PyDecimal(sign, '0', 0, 'NaN');

  const m = /^(\d*)(?:\.(\d*))?(?:[eE]([+-]?\d+))?$/.exec(body);
  if (!m) throw new Error(`Invalid decimal literal: ${s}`);
  const intPart = m[1] || '';
  const fracPart = m[2] || '';
  const expPart = m[3] ? parseInt(m[3], 10) : 0;
  let digits = (intPart + fracPart).replace(/^0+/, '');
  if (digits === '') digits = '0';
  return new PyDecimal(sign, digits, expPart - fracPart.length);
}

// Halve an even non-negative integer given as a digit string (string math,
// no floating point involved).
function halfDigitString(digits) {
  let out = '';
  let carry = 0;
  for (const ch of digits) {
    const v = carry * 10 + (ch.charCodeAt(0) - 48);
    const q = (v / 2) | 0;
    if (out !== '' || q !== 0) out += String(q);
    carry = v % 2;
  }
  return out === '' ? '0' : out;
}

// Exact division by 2, following decimal arithmetic rules: the preferred
// exponent of an exact quotient is exp(dividend) - exp(divisor). For an even
// coefficient c * 10^e the result is (c/2) * 10^e (trailing zeros kept); for
// an odd coefficient it is (c*5) * 10^(e-1).
export function decimalHalve(d) {
  if (d.special) return new PyDecimal(d.sign, d.digits, d.exp, d.special);
  if (d.digits === '0') return new PyDecimal(d.sign, '0', d.exp);
  const lastDigit = d.digits.charCodeAt(d.digits.length - 1) - 48;
  if (lastDigit % 2 === 0) {
    return new PyDecimal(d.sign, halfDigitString(d.digits), d.exp);
  }
  // odd coefficient: c / 2 = (c * 10) / 2 * 10^(e-1), and (c*10) is even
  return new PyDecimal(d.sign, halfDigitString(d.digits + '0'), d.exp - 1);
}

// str(Decimal): scientific notation when the exponent is positive or the
// adjusted exponent is below -6, plain fixed notation otherwise.
export function decimalToString(d) {
  if (d.special === 'Infinity') return d.sign + 'Infinity';
  if (d.special === 'NaN') return d.sign + 'NaN';

  const n = d.digits;
  const e = d.exp;
  const adjusted = e + n.length - 1;

  let body;
  if (e > 0 || adjusted < -6) {
    const mant = n.length > 1 ? n[0] + '.' + n.slice(1) : n;
    body = mant + 'E' + (adjusted < 0 ? '-' : '+') + String(Math.abs(adjusted));
  } else if (e === 0) {
    body = n;
  } else {
    const pointPos = n.length + e;
    if (pointPos > 0) {
      body = n.slice(0, pointPos) + '.' + n.slice(pointPos);
    } else {
      body = '0.' + '0'.repeat(-pointPos) + n;
    }
  }
  return d.sign + body;
}

