// pystr.mjs
// CPython repr() for strings (used in argparse / traceback error messages).

export function pyRepr(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (ch < ' ' || ch === '\x7f') {
      out += '\\x' + ch.charCodeAt(0).toString(16).padStart(2, '0');
    } else out += ch;
  }
  return out + quote;
}

