// money.mjs
// Re-implementation of the moneyed.Money behaviour used by the original
// script: construction from a float amount (converted via Decimal(str(amount)))
// and division by a number.

import { PyDecimal, decimalFromString, decimalHalve } from './pydecimal.mjs';
import { pyFloatRepr } from './pyfloat.mjs';
import { getCurrency, CurrencyDoesNotExist } from './currencies.mjs';

export { CurrencyDoesNotExist };

export class Money {
  // amount: JS number (a Python float) or an already-computed PyDecimal.
  constructor(amount, currency) {
    this.currency = getCurrency(currency);
    if (amount instanceof PyDecimal) {
      this.amount = amount;
    } else {
      // moneyed: Decimal(str(amount)) for non-Decimal input
      this.amount = decimalFromString(pyFloatRepr(amount));
    }
  }

  // moneyed's Money.__truediv__: returns Money(self.amount / other, currency).
  // The original script only ever divides by 2, which is exact under the
  // default decimal context, so only that divisor is supported.
  div(other) {
    if (other === 2) {
      return new Money(decimalHalve(this.amount), this.currency);
    }
    throw new Error(`unsupported divisor: ${other}`);
  }
}

