// test6.mjs
// Node.js (ESM) port of /workspace/dataset/test6.py:
//   parser --amount (float, required) --currency (str, required)
//   m = Money(amount, currency); print((m / 2).amount)

import { basename } from 'node:path';
import { parseArgs } from './argparse.mjs';
import { Money, CurrencyDoesNotExist } from './money.mjs';
import { decimalToString } from './pydecimal.mjs';
import { pyRepr } from './pystr.mjs';

const prog = basename(process.argv[1]);
const args = parseArgs(process.argv.slice(2), prog);

// 创建Money对象
let halved;
try {
  const m = new Money(args.amount, args.currency);
  // 除以2
  halved = m.div(2);
} catch (err) {
  if (err instanceof CurrencyDoesNotExist) {
    // Reproduce the uncaught-exception behaviour of the original program.
    const lines = [
      'Traceback (most recent call last):',
      '  File "moneyed/classes.py", line 400, in get_currency',
      `KeyError: ${pyRepr(err.code)}`,
      '',
      'During handling of the above exception, another exception occurred:',
      '',
      'Traceback (most recent call last):',
      '  File "test6.py", line 10, in <module>',
      '  File "moneyed/classes.py", line 196, in __init__',
      '  File "moneyed/classes.py", line 402, in get_currency',
      `moneyed.classes.CurrencyDoesNotExist: No currency with code ${err.code} is defined.`,
      `[PYI-${process.pid}:ERROR] Failed to execute script 'test6' due to unhandled exception!`,
    ];
    process.stderr.write(lines.join('\n') + '\n');
    process.exit(1);
  }
  throw err;
}

// 打印结果金额
console.log(decimalToString(halved.amount));

